    def finish_answer_candidate(stage, resolution_signature):
        body, _, evidence_wire, context, limits = original(resolutions, stage)
        signed = with_proof(body, context['actor']['keyId'], resolution_signature, 'resolution', limits)
        return {'checkpointCid': context['summary']['checkpointCid'], 'resolutionWire': frame(signed, limits),
                'approvalEvidenceWire': evidence_wire}

    def review_bytes_match_cid(raw, expected, selected_limits):
        try:
            limits = _limits_of(selected_limits)
            if (type(raw) not in (bytes, bytearray, memoryview)
                    or type(expected) is not str or re.fullmatch(r'sha256:[0-9a-f]{64}', expected) is None):
                return False
            if memoryview(raw).nbytes > limits['maxWireBytes']:
                return False
            raw = bytes(raw)
            if bytes_cid(raw) == expected:
                return True
            value = _capture(decode_json(raw), limits)
            profile = next((item for item in _CONTRACT['reviews'] if type(value) is dict
                            and item['version'] == value.get('version')), None)
            if (profile is None or value.get(profile['selfField']) != expected
                    or canonical_bytes(value, data_keys=profile['dataKeys']) != raw):
                return False
            body = {key: item for key, item in value.items() if key != profile['selfField']}
            return bytes_cid(canonical_bytes(body, data_keys=profile['dataKeys'])) == expected
        except (ClientError, ValueError, TypeError, OverflowError, RecursionError):
            return False

    return _Codec(prepare_answer_candidate, answer_candidate_approval_preimage,
                  prepare_answer_resolution, answer_resolution_preimage, finish_answer_candidate,
                  review_bytes_match_cid, _encode_signer_signature, _valid_signer_ids)
